  width: min(610px, 100%);
  margin: 45px auto 30px;
  border: 1px solid var(--ink);
  background: var(--paper);
  padding: clamp(24px, 5vw, 44px);
  box-shadow: 9px 9px 0 var(--ink);
  text-align: left;
  transform: rotate(-0.5deg);
}

.result-ticket-top {
  display: flex;
  justify-content: space-between;
  gap: 20px;
  align-items: flex-start;
}

.result-ticket-top span {
  color: var(--berry);
  font-family: "Courier New", monospace;
  font-size: 0.69rem;
  font-weight: 800;
  text-transform: uppercase;
}

.result-ticket h2 {
  margin: 7px 0 0;
  font-family: Georgia, serif;
  font-size: clamp(2rem, 6vw, 3.5rem);
  font-weight: 400;
  line-height: 1;
  letter-spacing: -0.05em;
}

.result-score {
  position: static;
  flex: 0 0 auto;
}

.result-facts {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  margin: 28px 0;
  border-block: 1px dashed var(--line);
}

.result-facts span {
  display: grid;
  gap: 4px;
  padding: 16px 12px;
  border-right: 1px dashed var(--line);
  font-size: 0.87rem;
  font-weight: 800;
}

.result-facts span:first-child {
  padding-left: 0;
}

.result-facts span:last-child {
  border-right: 0;
}

.result-facts small {
  color: var(--ink-soft);
  font-family: "Courier New", monospace;
  font-size: 0.57rem;
  text-transform: uppercase;
}

.result-order {
  margin-bottom: 18px;
}

.dietary-warning {
  color: var(--ink-soft);
  font-size: 0.67rem;
  line-height: 1.4;
}

.result-links {
  display: flex;
  flex-wrap: wrap;
  gap: 10px;
  margin-top: 22px;
}

.result-links a,
.result-links span {
  border: 1px solid var(--ink);
  border-radius: 999px;
  color: var(--ink);
  background: var(--white);
  padding: 10px 14px;
  font-size: 0.7rem;
  font-weight: 800;
  text-decoration: none;
}

.secondary-action {
  border: 1px solid var(--ink);
  border-radius: 999px;
  background: transparent;
  padding: 11px 18px;
  font-weight: 800;
  cursor: pointer;
}

.confetti-field i {
  position: absolute;
  display: block;
  width: 13px;
  height: 32px;
  border-radius: 999px;
  background: var(--tomato);
  transform: rotate(23deg);
}

.confetti-field i:nth-child(1) { top: 14%; left: 10%; }
.confetti-field i:nth-child(2) { top: 24%; right: 13%; background: var(--butter); transform: rotate(-40deg); }
.confetti-field i:nth-child(3) { top: 53%; left: 4%; background: var(--mint); transform: rotate(70deg); }
.confetti-field i:nth-child(4) { top: 62%; right: 6%; background: var(--berry); transform: rotate(-12deg); }
.confetti-field i:nth-child(5) { top: 8%; right: 32%; width: 20px; height: 20px; background: var(--mint); }
.confetti-field i:nth-child(6) { top: 44%; left: 18%; width: 18px; height: 18px; background: var(--butter); }

.fallback-layout {
  display: grid;
  grid-template-columns: 1fr 0.85fr;
  gap: clamp(44px, 8vw, 120px);
  align-items: center;
  text-align: left;
}

.fallback-copy h1 {
  font-size: clamp(4rem, 8vw, 7.5rem);
}

.fallback-copy > p:not(.eyebrow) {
  margin-left: 0;
}

.plate-card {
  overflow: hidden;
  border: 1px solid var(--ink);
  border-radius: 30px;
  background: var(--paper);
  box-shadow: 10px 10px 0 var(--ink);
  transform: rotate(1.2deg);
}

.plate-illustration {
  position: relative;
  height: 245px;
  background: var(--tomato);
}

.plate-main,
.plate-small {
  position: absolute;
  display: block;
  border: 4px solid var(--ink);
  border-radius: 50%;
  box-shadow: 7px 7px 0 rgba(42, 18, 53, 0.23);
}

.plate-main {
  width: 180px;
  height: 180px;
  left: calc(50% - 90px);
  top: 31px;
  background: repeating-conic-gradient(var(--butter) 0 13deg, var(--paper) 13deg 25deg);
  box-shadow: inset 0 0 0 35px var(--paper), 7px 7px 0 rgba(42, 18, 53, 0.23);
}

.plate-small {
  width: 69px;
  height: 69px;
  background: var(--mint);
}

.plate-small.one { left: 9%; top: 36px; }
.plate-small.two { right: 8%; bottom: 28px; background: var(--lavender); }

.plate-content {
  padding: 28px 32px 34px;
}

.plate-content h2 {
  margin: 8px 0 20px;
  font-family: Georgia, serif;
  font-size: 2rem;
  font-weight: 400;
  letter-spacing: -0.04em;
}

.plate-content ul {
  display: grid;
  grid-template-columns: repeat(2, 1fr);
  gap: 9px 16px;
  margin: 0;
  padding: 0;
  list-style: none;
}

.plate-content li {
  font-size: 0.78rem;
  font-weight: 700;
}

.plate-content li span {
  margin-right: 7px;
  color: var(--tomato);
}

.plate-content > p {
  margin: 22px 0 10px;
  padding-top: 18px;
  border-top: 1px dashed var(--line);
  color: var(--ink-soft);
  font-size: 0.78rem;
  line-height: 1.55;
}

.plate-content > small {
  color: var(--berry-dark);
  font-size: 0.65rem;
  font-weight: 700;
}

.fallback-actions {
  grid-column: 1 / -1;
  width: min(430px, 100%);
  margin: -65px 0 0;
}

footer {
  display: flex;
  justify-content: space-between;
  gap: 20px;
  padding: 24px 0 30px;
  border-top: 1px solid var(--line);
  color: var(--ink-soft);
  font-family: "Courier New", monospace;
  font-size: 0.62rem;
}

@media (max-width: 900px) {
  .topbar {
    grid-template-columns: 1fr auto;
  }

  .topbar-note {
    display: none;
  }

  .setup-layout,
  .fallback-layout {
    grid-template-columns: 1fr;
  }

  .setup-layout {
    gap: 52px;
    padding-top: 58px;
  }

  .hero-copy {
    position: static;
    padding-top: 0;
  }

  .hero-copy h1 {
    max-width: 650px;
  }

  .fallback-layout {
    width: min(620px, 100%);
    margin: 0 auto;
  }

  .fallback-actions {
    margin: 0;
  }
}

@media (max-width: 560px) {
  .app-shell {
    padding: 0 15px;
  }

  .topbar {
    height: 70px;
  }

  .tiny-button {
    border: 0;
    background: transparent;
    padding-right: 0;
  }

  .setup-layout {
    padding: 40px 0 70px;
  }

  .hero-copy h1 {
    font-size: clamp(3.4rem, 16vw, 5rem);
  }

  .hero-lede {
    margin: 25px 0;
  }

  .setup-card {
    margin-inline: -3px;
    padding: 24px 18px 28px;
    border-radius: 24px;
  }

  .party-picker {
    gap: 4px;
  }

  .party-picker button {
    border-radius: 9px;
    font-size: 0.76rem;
  }

  .name-grid,
  .split-fields {
    grid-template-columns: 1fr;
  }

  .vibe-grid {
    grid-template-columns: repeat(2, 1fr);
  }

  .location-row {
    align-items: flex-start;
    flex-direction: column;
  }

  .location-button {
    width: 100%;
  }

  .deck-layout {
    padding-top: 24px;
  }

  .deck-header {
    align-items: flex-start;
  }

  .deck-header h1 {
    font-size: 2.35rem;
  }

  .participant-stack {
    max-width: 116px;
    flex-wrap: wrap-reverse;
  }

  .participant-stack span {
    width: 32px;
    height: 32px;
  }

  .card-stage {
    width: 100%;
    height: 574px;
  }

  .food-art {
    height: 220px;
  }

  .food-art::before {
    top: 22px;
  }

  .card-body {
    padding: 19px 20px 22px;
  }

  .card-body h2 {
    font-size: 2rem;
  }

  .swipe-actions {
    margin-top: 22px;
  }

  .gesture-help {
    display: none;
  }

  .result-layout,
  .fallback-layout {
    padding-top: 65px;
  }

  .result-layout > h1,
  .fallback-copy h1 {
    font-size: 3.9rem;
  }

  .result-ticket {
    padding: 25px 20px;
    box-shadow: 6px 6px 0 var(--ink);
  }

  .result-facts span {
    padding: 13px 7px;
    font-size: 0.74rem;
  }

  .plate-content {
    padding: 25px 22px 30px;
  }

  footer {
    display: grid;
  }
}

@media (prefers-reduced-motion: reduce) {
  *,
  *::before,
  *::after {
    scroll-behavior: auto !important;
    transition-duration: 0.01ms !important;
    animation-duration: 0.01ms !important;
    animation-iteration-count: 1 !important;
  }
}

